"""Release-bank and flow-epoch replay for the deployment contract."""


class SessionEngine:
    """Atomic installs, resident banks and interleaved flow epochs."""

    def __init__(self, models, capacity):
        self.models = models
        self.capacity = capacity
        self.current = None
        self.residents = {}
        self.pins = {}
        self.active = {}
        self.opened = {}
        self.installs = []
        self.decisions = []

    # ------------------------------------------------------------------ banks
    def usage(self):
        range_used = exact_used = 0
        for identifier, entries in self.residents.items():
            if self.models[identifier]['mode'] == 'range':
                range_used += entries
            else:
                exact_used += entries
        return {'range': range_used, 'exact': exact_used}

    def install(self, identifier, at):
        model = self.models[identifier]
        entries = model['entries']
        status = 'oversize' if entries > self.capacity[model['mode']] else None
        if status is None:
            prospective = dict(self.residents)
            previous = self.current
            if (previous is not None and previous != identifier and
                    self.pins.get(previous, 0) == 0):
                del prospective[previous]
            prospective[identifier] = entries
            range_used = exact_used = 0
            for resident, resident_entries in prospective.items():
                if self.models[resident]['mode'] == 'range':
                    range_used += resident_entries
                else:
                    exact_used += resident_entries
            if (range_used > self.capacity['range'] or
                    exact_used > self.capacity['exact']):
                status = 'busy'
            else:
                status = 'ok'
                self.residents = prospective
                self.current = identifier
        self.installs.append({'at': at, 'id': identifier, 'status': status,
                              'resident': sorted(self.residents),
                              'used': self.usage()})

    # ----------------------------------------------------------------- epochs
    def open_flow(self, flow, at):
        if flow in self.active:
            raise ValueError('invalid_request')
        if self.current is None:
            raise ValueError('invalid_request')
        epoch = self.opened.get(flow, 0)
        self.opened[flow] = epoch+1
        self.active[flow] = {
            'flow': flow, 'epoch': epoch, 'release': self.current,
            'model': self.models[self.current], 'features': [], 'consumed': 0,
            'direction': None, 'last_timestamp': None, 'committed': False,
            'state': 0,
        }
        self.pins[self.current] = self.pins.get(self.current, 0)+1

    def _commit(self, epoch, reason, seen, at, rule=None, start=None, klass=None):
        model = epoch['model']
        if reason != 'segment':
            width = model['width']
            features = epoch['features'][:width]
            features = features + [1514]*(width-len(features))
            klass = model['predict'](features)
        self.decisions.append({
            'flow': epoch['flow'], 'epoch': epoch['epoch'],
            'release': epoch['release'], 'at': at, 'seen': seen,
            'class': klass, 'reason': reason, 'rule': rule, 'start': start,
        })
        epoch['committed'] = True

    def packet(self, flow, timestamp, source, length, at):
        epoch = self.active.get(flow)
        if epoch is None:
            raise ValueError('invalid_request')
        previous = epoch['last_timestamp']
        if previous is not None and timestamp < previous:
            raise ValueError('invalid_request')
        model = epoch['model']
        if epoch['direction'] is None:
            epoch['direction'] = source
        encoded = 1514+length if source == epoch['direction'] else 1514-length
        gap = None if previous is None else timestamp-previous
        epoch['last_timestamp'] = timestamp
        if epoch['committed']:
            return
        width = model['width']
        if epoch['consumed'] >= width and gap is not None and gap > model['idle_us']:
            self._commit(epoch, 'idle', epoch['consumed'], at)
            return
        epoch['features'].append(encoded)
        epoch['consumed'] += 1
        automaton = model['automaton']
        if not automaton.ids:
            state = None
        else:
            state = automaton.advance(epoch['state'], encoded)
            epoch['state'] = state
        if state is not None and state & automaton.match_mask:
            rank = automaton.first_match(state)
            length = automaton.lengths[rank]
            self._commit(epoch, 'segment', epoch['consumed'], at,
                         rule=automaton.ids[rank], start=epoch['consumed']-length,
                         klass=automaton.classes[rank])
            return
        if epoch['consumed'] > model['packet_limit']:
            self._commit(epoch, 'limit', epoch['consumed'], at)

    def close_flow(self, flow, at):
        epoch = self.active.pop(flow, None)
        if epoch is None:
            raise ValueError('invalid_request')
        if not epoch['committed']:
            self._commit(epoch, 'close', epoch['consumed'], at)
        release = epoch['release']
        remaining = self.pins.get(release, 0)-1
        if remaining > 0:
            self.pins[release] = remaining
        else:
            self.pins.pop(release, None)
            if self.current != release:
                self.residents.pop(release, None)

    # ----------------------------------------------------------------- replay
    def execute(self, blocks):
        at = 0
        for block in blocks:
            for event in block:
                operation = event[0]
                if operation == 'install':
                    self.install(event[1], at)
                elif operation == 'open':
                    self.open_flow(event[1], at)
                elif operation == 'packet':
                    self.packet(event[1], event[2], event[3], event[4], at)
                else:
                    self.close_flow(event[1], at)
                at += 1
        if self.active:
            raise ValueError('invalid_request')
        final = {'current': self.current, 'resident': sorted(self.residents),
                 'used': self.usage()}
        return self.installs, self.decisions, final
